from pathlib import Path
import re
p = Path('/home/ubuntu/qgram/client/src/pages/Home.tsx')
s = p.read_text()
new_block = r'''{tab === "settings" && <section className="grid overflow-hidden rounded-[16px] border border-[#e8e8e8] bg-white md:grid-cols-[230px_1fr]" dir="ltr"><nav className="border-b border-[#eeeeee] p-2 md:border-b-0 md:border-r">{[{ key: "profile", title: "ویرایش پروفایل", icon: <UserRound size={17} /> }, { key: "notifications", title: "اعلان‌ها", icon: <Bell size={17} /> }, { key: "privacy", title: "حریم خصوصی", icon: <UsersRound size={17} /> }, { key: "comments", title: "کامنت‌ها و تگ‌ها", icon: <MessageCircle size={17} /> }, { key: "language", title: "زبان و رسانه", icon: <Sparkles size={17} /> }, { key: "account", title: "وضعیت فعالیت و حساب", icon: <Settings size={17} /> }].map((item) => <button type="button" key={item.key} onClick={() => setSettingsSection(item.key)} className={`flex w-full items-center gap-3 rounded-lg px-3 py-3 text-left text-xs font-bold ${settingsSection === item.key ? "bg-[#f1f1f1] text-[#111]" : "text-[#777] hover:bg-[#fafafa]"}`}><span>{item.icon}</span><span dir="rtl">{item.title}</span></button>)}</nav><div className="min-h-[470px] p-6" dir="rtl">{settingsSection === "profile" && <div><h2 className="text-xl font-bold">ویرایش پروفایل</h2><p className="mt-2 text-xs leading-6 text-[#888]">این تغییرات مستقیماً در حساب کاربری ذخیره می‌شوند.</p><div className="mt-6 space-y-4"><label className="block text-xs font-bold">نام کاربری<input value={profileUsername} onChange={(event) => setProfileUsername(event.target.value)} className="mt-2 h-11 w-full rounded-lg border border-[#ddd] px-3 text-sm outline-none" /></label><label className="block text-xs font-bold">Bio<textarea value={profileBio} onChange={(event) => setProfileBio(event.target.value)} className="mt-2 min-h-24 w-full rounded-lg border border-[#ddd] p-3 text-sm outline-none" /></label><button type="button" disabled={profileMutation.isPending} onClick={() => profileMutation.mutate({ username: profileUsername, bio: profileBio }, { onSuccess: () => toast("پروفایل در دیتابیس ذخیره شد."), onError: () => toast("ذخیره پروفایل انجام نشد.") })} className="rounded-lg bg-[#111] px-5 py-3 text-xs font-bold text-white disabled:opacity-50">{profileMutation.isPending ? "در حال ذخیره…" : "ذخیره تغییرات"}</button></div></div>}{settingsSection === "privacy" && <div><h2 className="text-xl font-bold">حریم خصوصی حساب</h2><p className="mt-2 text-xs leading-6 text-[#888]">تنظیمات این بخش برای حساب ذخیره می‌شوند و با refresh از بین نمی‌روند.</p><div className="mt-7 flex items-center justify-between border-b border-[#eee] py-5"><div><b className="block text-sm">حساب خصوصی</b><small className="mt-1 block text-xs text-[#999]">فقط دنبال‌کننده‌های تأییدشده پست‌ها را ببینند.</small></div><button type="button" role="switch" aria-checked={privateAccount} onClick={() => { const next = !privateAccount; setPrivateAccount(next); settingsMutation.mutate({ privateAccount: next }); }} className={`h-7 w-12 rounded-full p-1 transition ${privateAccount ? "bg-[#111]" : "bg-[#ddd]"}`}><span className={`block h-5 w-5 rounded-full bg-white transition ${privateAccount ? "translate-x-5" : "translate-x-0"}`} /></button></div><div className="flex items-center justify-between border-b border-[#eee] py-5"><div><b className="block text-sm">نمایش وضعیت فعالیت</b><small className="mt-1 block text-xs text-[#999]">آخرین فعالیتت به دیگران نشان داده شود.</small></div><button type="button" role="switch" aria-checked={liveSettings?.activityStatus ?? true} onClick={() => settingsMutation.mutate({ activityStatus: !(liveSettings?.activityStatus ?? true) })} className={`h-7 w-12 rounded-full p-1 transition ${(liveSettings?.activityStatus ?? true) ? "bg-[#111]" : "bg-[#ddd]"}`}><span className="block h-5 w-5 rounded-full bg-white" /></button></div></div>}{settingsSection === "comments" && <div><h2 className="text-xl font-bold">کامنت‌ها، تگ‌ها و منشن‌ها</h2><p className="mt-2 text-xs leading-6 text-[#888]">مشخص کن چه کسانی بتوانند با محتوای تو تعامل داشته باشند.</p><div className="mt-6 flex items-center justify-between border-b border-[#eee] py-5"><b className="text-sm">اجازه‌ی کامنت</b><button type="button" role="switch" aria-checked={allowComments} onClick={() => { const next = !allowComments; setAllowComments(next); settingsMutation.mutate({ allowComments: next }); }} className={`h-7 w-12 rounded-full p-1 transition ${allowComments ? "bg-[#111]" : "bg-[#ddd]"}`}><span className={`block h-5 w-5 rounded-full bg-white transition ${allowComments ? "translate-x-5" : "translate-x-0"}`} /></button></div><div className="mt-5"><b className="text-sm">چه کسانی بتوانند تو را تگ کنند؟</b><div className="mt-3 space-y-2">{[{ value: "everyone", label: "همه" }, { value: "following", label: "افرادی که دنبال می‌کنی" }, { value: "nobody", label: "هیچ‌کس" }].map((item) => <label key={item.value} className="flex items-center gap-3 rounded-lg border border-[#eee] px-3 py-3 text-xs"><input type="radio" name="allowTags" checked={(liveSettings?.allowTags ?? "everyone") === item.value} onChange={() => settingsMutation.mutate({ allowTags: item.value as "everyone" | "following" | "nobody" })} />{item.label}</label>)}</div></div></div>}{settingsSection === "notifications" && <div><h2 className="text-xl font-bold">اعلان‌ها</h2><p className="mt-2 text-xs leading-6 text-[#888]">نوع اعلان‌های داخل برنامه و ایمیل را انتخاب کن.</p>{[{ key: "pushNotifications", label: "اعلان‌های داخل برنامه", value: liveSettings?.pushNotifications ?? true }, { key: "emailNotifications", label: "اعلان‌های ایمیلی", value: liveSettings?.emailNotifications ?? true }, { key: "archiveStories", label: "ذخیره خودکار استوری‌ها", value: liveSettings?.archiveStories ?? true }].map((item) => <div key={item.key} className="flex items-center justify-between border-b border-[#eee] py-5"><b className="text-sm">{item.label}</b><button type="button" role="switch" aria-checked={item.value} onClick={() => settingsMutation.mutate({ [item.key]: !item.value })} className={`h-7 w-12 rounded-full p-1 transition ${item.value ? "bg-[#111]" : "bg-[#ddd]"}`}><span className="block h-5 w-5 rounded-full bg-white" /></button></div>)}</div>}{settingsSection === "language" && <div><h2 className="text-xl font-bold">زبان برنامه</h2><p className="mt-2 text-xs leading-6 text-[#888]">انتخاب زبان در حساب ذخیره می‌شود.</p><div className="mt-6 space-y-2">{[{ value: "fa", label: "فارسی" }, { value: "en", label: "English" }, { value: "ar", label: "العربية" }].map((item) => <button type="button" key={item.value} onClick={() => settingsMutation.mutate({ language: item.value }, { onSuccess: () => toast(`زبان ${item.label} ذخیره شد.`) })} className="flex w-full items-center justify-between rounded-lg border border-[#eee] px-4 py-3 text-sm"><span>{item.label}</span>{(liveSettings?.language ?? "fa") === item.value && <Check size={16} />}</button>)}</div></div>}{settingsSection === "account" && <div><h2 className="text-xl font-bold">وضعیت فعالیت و حساب</h2><p className="mt-2 text-xs leading-6 text-[#888]">کنترل وضعیت فعالیت و امکانات حساب حرفه‌ای.</p><div className="mt-6 rounded-lg border border-[#eee] p-4"><b className="text-sm">نوع حساب فعلی</b><p className="mt-2 text-xs text-[#999]">حساب شخصی کیو گرام</p></div><button type="button" onClick={() => toast("درخواست حساب حرفه‌ای ثبت شد.")} className="mt-4 flex w-full items-center justify-between rounded-lg border border-[#eee] px-4 py-4 text-sm"><span>درخواست حساب حرفه‌ای</span><ChevronLeft size={16} /></button></div>}</div></section>}'''
pattern = r'\{tab === "settings" && <section[\s\S]*?</section>\}'
if not re.search(pattern, s):
    raise SystemExit("settings block not found")
s = re.sub(pattern, new_block, s, count=1)
p.write_text(s)
